from produire import produire,paras,table,steps
from medicaments import amoxicilline
parts=[
('L’otite moyenne aiguë associe un épisode inflammatoire récent et un épanchement de l’oreille moyenne. Les {distinctions diagnostiques} la séparent d’une rougeur isolée ou d’un épanchement non aigu.',paras('L’otalgie et les symptômes généraux sont confrontés à l’otoscopie. Une otite séromuqueuse peut donner une gêne auditive avec liquide rétrotympanique sans la même inflammation aiguë.')),
('L’affection est fréquente chez l’enfant et peut suivre une infection respiratoire. Les {éléments de contexte} influencent surtout la décision thérapeutique.',paras('Âge, atteinte bilatérale, perforation, gravité et possibilité de suivi comptent. Chez l’adulte, les données justifiant une antibiothérapie systématique sont limitées et la stratégie suisse permet une prescription retardée dans certaines situations.')),
('Une dysfonction tubaire favorise l’accumulation de liquide et l’inflammation. Les {mécanismes de douleur} comprennent distension et pression sur le tympan.',paras('La perforation spontanée peut laisser s’écouler le contenu de l’oreille moyenne et diminuer la douleur. Cette diminution ne signifie pas nécessairement guérison ; audition, tympan et complications restent à contrôler.')),
('Rechercher une mastoïdite ou une extension neurologique. Les {signes d’alarme} imposent une orientation urgente.',paras('Pavillon décollé, tuméfaction rétroauriculaire, douleur mastoïdienne importante, sepsis, méningisme, paralysie faciale ou vertige marqué nécessitent une évaluation hospitalière. Chez le jeune nourrisson altéré, rechercher une infection systémique au-delà de l’oreille.')),
('L’entretien précise durée, fièvre, apports et écoulement. Les {questions de décision} incluent âge, épisodes précédents et traitement récent.',paras('Demander antibiothérapie dans les trente jours, récidives, allergie, immunodépression et suivi disponible. Chez l’enfant, apprécier douleur, sommeil, alimentation et état général plutôt que se fonder uniquement sur le fait de toucher son oreille.')),
('L’otoscopie recherche bombement et épanchement associés à l’inflammation. Les {éléments d’examen} déterminent aussi gravité et latéralité.',paras('Examiner les deux oreilles et la région mastoïdienne. Un tympan rouge pendant les pleurs ne suffit pas ; préciser perforation, liquide, mobilité si l’examen adapté est réalisable, et inflammation du conduit.')),
('Le {diagnostic différentiel} sépare atteinte externe, moyenne non aiguë et douleur projetée. Une gêne auditive après guérison ne prouve pas une nouvelle infection.',table(['Constat','Orientation'],[['Tragus douloureux et conduit œdématié.','Otite externe.'],['Épanchement sans inflammation aiguë.','Otite séromuqueuse.'],['Douleur après variation de pression.','Barotraumatisme.'],['Oreille normale, mastication ou déglutition douloureuse.','Cause dentaire, articulaire ou pharyngée.']])) ,
('Le diagnostic positif exige une concordance clinique et otoscopique. Les {critères d’épanchement} renforcent la certitude.',paras('Le bombement tympanique est un argument important dans le tableau aigu. Un écoulement récent peut provenir d’une perforation, à distinguer d’une otite externe ; réexaminer si le tympan n’est pas visible.')),
('Aucune imagerie n’est nécessaire pour chaque forme simple. Les {examens complémentaires} sont réservés au doute, à l’évolution ou aux complications.',paras('Une évaluation auditive ou tympanométrique peut être indiquée pour un épanchement persistant. L’imagerie et les prélèvements spécialisés sont décidés en cas de complication ; la biologie ne remplace pas l’otoscopie.')),
('La {stratégie suisse} associe antalgie et décision antibiotique individualisée. Les délais de surveillance n’autorisent jamais à attendre une aggravation grave.',steps('Évaluer gravité et complications puis traiter la douleur.', 'La directive SSI recommande un antibiotique immédiat pour une atteinte bilatérale avant deux ans ; une perforation est aussi un contexte de bénéfice accru à considérer.', 'Si une stratégie retardée est retenue, réévaluer à 24–48 heures avant deux ans, et à 48–72 heures après deux ans ou chez l’adulte, selon symptômes.', 'Choisir antibiotique, dose, durée et suivi en fonction de l’âge, du tympan et de la préparation.')),
('L’antalgie est indiquée indépendamment de l’antibiothérapie. Les {repères médicamenteux} distinguent dose de notice et stratégie clinique.',paras('Décongestionnants et antihistaminiques n’ont pas de bénéfice démontré dans la directive SSI et ne sont pas recommandés pour cette indication. Les gouttes d’otite externe ne remplacent pas le traitement de l’oreille moyenne.', '@@MEDICAMENTS@@')),
('Le {suivi} vérifie symptômes, tympan et audition si nécessaire. Une réapparition fébrile ou douloureuse impose un contrôle.',paras('Expliquer le délai d’observation et les signes d’urgence ; vérifier l’accès à une nouvelle consultation. Une persistance d’épanchement avec retentissement auditif ou langagier demande une évaluation adaptée, pas des antibiotiques répétés à l’aveugle.')),
('Une rougeur tympanique isolée ne suffit pas. Âge, bilatéralité, perforation et gravité guident le traitement. L’antalgie accompagne toute stratégie. Mastoïdite et signes neurologiques doivent être reconnus sans délai.','')]
quiz=[('Un tympan rouge seul prouve-t-il l’otite moyenne aiguë ?','Non.'),('Quel élément otoscopique est particulièrement utile ?','Le bombement associé à l’épanchement et au tableau aigu.'),('Un enfant qui se touche l’oreille suffit-il au diagnostic ?','Non : l’examen est nécessaire.'),('L’épanchement séromuqueux impose-t-il toujours un antibiotique ?','Non.'),('Une perforation peut-elle diminuer la douleur ?','Oui, sans prouver la guérison.'),('Quel signe rétroauriculaire inquiète ?','Tuméfaction avec pavillon décollé, évoquant notamment une mastoïdite.'),('Quelle situation SSI demande un antibiotique immédiat ?','L’atteinte bilatérale chez l’enfant de moins de deux ans.'),('Quel délai de réévaluation en stratégie retardée avant deux ans ?','24 à 48 heures, plus tôt si aggravation.'),('Et après deux ans ou chez l’adulte ?','48 à 72 heures selon symptômes.'),('Quelle durée pédiatrique SSI en cas de perforation ?','Dix jours lorsque l’antibiothérapie est retenue.'),('La répartition SSI en deux prises est-elle celle d’Amoxi-Mepha cité ?','Non : cette notice indique trois à quatre prises ; la divergence doit être explicitée.'),('Les décongestionnants sont-ils recommandés de routine ?','Non.'),('Les gouttes externes traitent-elles toute otite moyenne ?','Non.'),('Une audition durablement gênée après l’épisode mérite-t-elle un suivi ?','Oui, avec évaluation adaptée du retentissement et de l’épanchement.')]
produire(2,parts,quiz,(1,2,8,17,24),amoxicilline)
